KG42.register("rules-8d456e154870b8746c20f4bc",{"id":"07-nash_bargaining::v141-c-R009","paper":"07-nash_bargaining","record":{"rule_id":"v141-c-R009","mechanism_id":"v141-a-M01","name":"Market payment","process_stage":"settlement","market_meaning":"Social operating cost minimization P1 is solved before the trading microgrids determine their payments through P2. Scope: The two-stage decomposition of NBP for interconnected microgrids; P1 covers all microgrids and P2 covers the trading set M′. P2 uses each trading microgrid's operating-cost reduction from the optimal P1 solution to maximize the product of gains remaining after trading payments. Scope: Determination of P2 payments for microgrids in M′ using the optimal P1 solution. Participation in P2 payment bargaining is conditional on having a nonzero inter-microgrid trading allocation from P1. Scope: Eligibility of interconnected microgrids for P2 payment bargaining following P1 allocation. Condition: The microgrid has a nonzero energy trading vector e_i in the P1 solution, placing it in M′. Identifying the group of trading microgrids after excluding non-participants precedes allocating that group's benefits through payment bargaining. Scope: Identification of the active trading group M′ and allocation of its members' benefits through P2. The virtual clearing house provides the clearing service for inter-microgrid payments. Scope: The virtual clearing house's payment-clearing service for participating interconnected microgrids. Bilateral payment entries must balance: π_{i,j} + π_{j,i} = 0. Scope: Bilateral payment entries for every distinct pair of interconnected microgrids. Operating cost plus net trading payment must not exceed the microgrid's minimized cost without inter-microgrid trading. Scope: The individual-rationality restriction on each microgrid's net trading payment. Condition: The microgrid participates in inter-microgrid energy trading. Payments are determined through bargaining and need not be linear in the exchanged energy. Scope: Payments negotiated between interconnected microgrids.","independence_rationale":"Relations governed by the approved function settlement.payment under the fixed relation-ownership template. Conditional branches retain their explicit scope in local constraints.","V":["clearing.inter_area","clearing.social_welfare","coordination.local_operator","matching.counterparties","settlement.payment"],"E":[{"edge_id":"v141-c-R009-E001","source":"clearing.social_welfare","target":"settlement.payment","type":"links","constraint_ids":["v141-c-R009-C002"],"evidence_ids":["v141-b-g02-E19"]},{"edge_id":"v141-c-R009-E002","source":"clearing.social_welfare","target":"settlement.payment","type":"precedes","constraint_ids":["v141-c-R009-C001"],"evidence_ids":["v141-b-g02-E17"]},{"edge_id":"v141-c-R009-E003","source":"coordination.local_operator","target":"settlement.payment","type":"links","constraint_ids":["v141-c-R009-C005"],"evidence_ids":["v141-b-g02-E37"]},{"edge_id":"v141-c-R009-E004","source":"matching.counterparties","target":"settlement.payment","type":"precedes","constraint_ids":["v141-c-R009-C004"],"evidence_ids":["v141-b-g02-E17","v141-b-g02-E21"]},{"edge_id":"v141-c-R009-E005","source":"settlement.payment","target":"clearing.inter_area","type":"conditional_on","constraint_ids":["v141-c-R009-C003"],"evidence_ids":["v141-b-g02-E18"]}],"omega":{"market_type":"DEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"settlement","context_text":"Bilateral payment entries for every distinct pair of interconnected microgrids. | Determination of P2 payments for microgrids in M′ using the optimal P1 solution. | Eligibility of interconnected microgrids for P2 payment bargaining following P1 allocation. | Identification of the active trading group M′ and allocation of its members' benefits through P2. | Payments negotiated between interconnected microgrids. | The individual-rationality restriction on each microgrid's net trading payment. | The two-stage decomposition of NBP for interconnected microgrids; P1 covers all microgrids and P2 covers the trading set M′. | The virtual clearing house's payment-clearing service for participating interconnected microgrids.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-e05","v141-b-g01-e22","v141-b-g01-e27","v141-b-g02-E17","v141-b-g02-E18","v141-b-g02-E19","v141-b-g02-E21","v141-b-g02-E37"]},"x":[{"variable_id":"v141-c-R009-x-pi-ij","symbol":"π_{i,j}","meaning":"Payment made by microgrid i to microgrid j for inter-microgrid energy trading; π_{i,j} > 0 means i pays j, π_{i,j} \u003c 0 means i receives payment from j. Bargained decision variable of the P2 payment-bargaining problem.","kind":"operational","domain":"signed real (π_{i,j} > 0 if i pays j; π_{i,j} \u003c 0 if i receives from j)","unit":null,"indices":["i ∈ M","j ∈ M\\i"],"evidence_ids":["v141-b-g01-e27","v141-b-g02-E19"]},{"variable_id":"v141-c-R009-x-pi-i","symbol":"π_i = {π_{i,j}, ∀j ∈ M\\i}","meaning":"Payment vector of microgrid i over all other interconnected microgrids; the decision-variable set of the P2 payment-bargaining problem is {π_i, i ∈ M′}.","kind":"operational","domain":"vector over j ∈ M\\i of signed real payments","unit":null,"indices":["i ∈ M′","j ∈ M\\i"],"evidence_ids":["v141-b-g01-e27","v141-b-g02-E19"]}],"theta":[{"parameter_id":"v141-c-R009-th-non","symbol":"C_i^{Non}","meaning":"Minimized cost that microgrid i can achieve without trading energy with other microgrids (the optimal value of P-MGi); the disagreement point of the individual-rationality constraint (18) and the benchmark of δ_i^*.","value":{"kind":"symbolic","number_value":null,"text_value":"C_i^{Non}"},"unit":null,"indices":["i ∈ M"],"evidence_ids":["v141-b-g01-e05","v141-b-g02-E19"]},{"parameter_id":"v141-c-R009-th-delta","symbol":"δ_i^*","meaning":"Operating cost reduction of microgrid i based on the optimal solution of Problem P1: δ_i^* ≜ C_i^{Non} − CO_i(q_i^*, x_n^*, r_{c,i}^*, r_{d,i}^*).","value":{"kind":"symbolic","number_value":null,"text_value":"δ_i^*"},"unit":null,"indices":["i ∈ M′"],"evidence_ids":["v141-b-g02-E19"]},{"parameter_id":"v141-c-R009-th-ei","symbol":"e_i","meaning":"Inter-microgrid energy trading vector of microgrid i, e_i = {e_{i,j}^t, ∀t ∈ T, ∀j ∈ M\\i}; used here at its P1-optimal value. A nonzero e_i places i in the trading set M′. Scope note: e_i is a decision variable of the preceding P1/clearing problem and a fixed input to this settlement rule.","value":{"kind":"symbolic","number_value":null,"text_value":"e_i"},"unit":null,"indices":["i ∈ M","j ∈ M\\i","t ∈ T"],"evidence_ids":["v141-b-g01-e27","v141-b-g02-E18"]}],"phi":[{"constraint_id":"v141-c-R009-C001","kind":"procedural","role":"core","statement":"Social operating cost minimization P1 is solved before the trading microgrids determine their payments through P2. Scope: The two-stage decomposition of NBP for interconnected microgrids; P1 covers all microgrids and P2 covers the trading set M′.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["clearing.social_welfare","settlement.payment"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g02-E17"]},{"constraint_id":"v141-c-R009-C002","kind":"mathematical","role":"core","statement":"P2 uses each trading microgrid's operating-cost reduction from the optimal P1 solution to maximize the product of gains remaining after trading payments. Scope: Determination of P2 payments for microgrids in M′ using the optimal P1 solution.","expression":"P2: max_{π_i, i∈M′} ∏_{i∈M′} ( δ_i^* − C_e(π_i) ), subject to (16) and (18), with δ_i^* ≜ C_i^{Non} − CO_i(q_i^*, x_n^*, r_{c,i}^*, r_{d,i}^*).","formalization_origin":"source","template_id":null,"members":["clearing.social_welfare","settlement.payment"],"variable_refs":["v141-c-R009-x-pi-i","v141-c-R009-x-pi-ij"],"parameter_refs":["v141-c-R009-th-delta"],"evidence_ids":["v141-b-g02-E19"]},{"constraint_id":"v141-c-R009-C003","kind":"logical","role":"core","statement":"Participation in P2 payment bargaining is conditional on having a nonzero inter-microgrid trading allocation from P1. Scope: Eligibility of interconnected microgrids for P2 payment bargaining following P1 allocation. Condition: The microgrid has a nonzero energy trading vector e_i in the P1 solution, placing it in M′.","expression":"e_i ≠ 0 ⇒ i ∈ M′ (i participates in P2); M′ = { i ∈ M : i trades energy with other microgrids }, so i ∈ M′ ⇒ e_i ≠ 0; with e_i = { e_{i,j}^t, ∀t ∈ T, ∀j ∈ M\\i }; for j ∈ M\\M′, j does not participate in P2 and its operating cost equals its disagreement point C_j^{Non}.","formalization_origin":"source","template_id":null,"members":["settlement.payment","clearing.inter_area"],"variable_refs":[],"parameter_refs":["v141-c-R009-th-ei"],"evidence_ids":["v141-b-g02-E18","v141-b-g02-E17"]},{"constraint_id":"v141-c-R009-C004","kind":"procedural","role":"core","statement":"Identifying the group of trading microgrids after excluding non-participants precedes allocating that group's benefits through payment bargaining. Scope: Identification of the active trading group M′ and allocation of its members' benefits through P2.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["matching.counterparties","settlement.payment"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g02-E17","v141-b-g02-E21"]},{"constraint_id":"v141-c-R009-C005","kind":"procedural","role":"core","statement":"The virtual clearing house provides the clearing service for inter-microgrid payments. Scope: The virtual clearing house's payment-clearing service for participating interconnected microgrids.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["coordination.local_operator","settlement.payment"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g02-E37"]},{"constraint_id":"v141-c-R009-C006","kind":"mathematical","role":"core","statement":"Bilateral payment entries must balance: π_{i,j} + π_{j,i} = 0. Scope: Bilateral payment entries for every distinct pair of interconnected microgrids.","expression":"π_{i,j} + π_{j,i} = 0, ∀j ∈ M\\i, ∀i ∈ M. (16)","formalization_origin":"source","template_id":null,"members":["settlement.payment"],"variable_refs":["v141-c-R009-x-pi-ij"],"parameter_refs":[],"evidence_ids":["v141-b-g01-e22","v141-b-g02-E10"]},{"constraint_id":"v141-c-R009-C007","kind":"mathematical","role":"core","statement":"Operating cost plus net trading payment must not exceed the microgrid's minimized cost without inter-microgrid trading. Scope: The individual-rationality restriction on each microgrid's net trading payment. Condition: The microgrid participates in inter-microgrid energy trading.","expression":"CO_i(q_i, x_n, r_{c,i}, r_{d,i}) + C_e(π_i) ≤ C_i^{Non}, ∀i ∈ M. (18)","formalization_origin":"source","template_id":null,"members":["settlement.payment"],"variable_refs":["v141-c-R009-x-pi-i"],"parameter_refs":["v141-c-R009-th-non"],"evidence_ids":["v141-b-g01-e05","v141-b-g02-E13"]},{"constraint_id":"v141-c-R009-C008","kind":"procedural","role":"core","statement":"Payments are determined through bargaining and need not be linear in the exchanged energy. Scope: Payments negotiated between interconnected microgrids.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["settlement.payment"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g01-e27"]},{"constraint_id":"v141-c-R009-C009","kind":"mathematical","role":"supporting","statement":"The extra cost of an interconnected microgrid is its total trading payment to all other microgrids: C_e(π_i) = Σ_{j∈M\\i} π_{i,j}. (Payment aggregation entering the individual-rationality constraint (18) and the P2 objective.)","expression":"C_e(π_i) = Σ_{j∈M\\i} π_{i,j}, ∀i ∈ M.","formalization_origin":"source","template_id":null,"members":["settlement.payment"],"variable_refs":["v141-c-R009-x-pi-i","v141-c-R009-x-pi-ij"],"parameter_refs":[],"evidence_ids":["v141-b-g01-e23","v141-b-g02-E12"]},{"constraint_id":"v141-c-R009-C010","kind":"mathematical","role":"supporting","statement":"Definition of the operating-cost reduction used in the P2 objective: δ_i^* ≜ C_i^{Non} − CO_i(q_i^*, x_n^*, r_{c,i}^*, r_{d,i}^*) denotes the operating cost reduction of microgrid i based on the optimal solution of Problem P1.","expression":"δ_i^* ≜ C_i^{Non} − CO_i(q_i^*, x_n^*, r_{c,i}^*, r_{d,i}^*), i ∈ M′.","formalization_origin":"source","template_id":null,"members":["clearing.social_welfare","settlement.payment"],"variable_refs":[],"parameter_refs":["v141-c-R009-th-non","v141-c-R009-th-delta"],"evidence_ids":["v141-b-g02-E19"]}],"pi":[{"evidence_id":"v141-b-g01-e05","location":{"location_id":"src-7e85444402-p05-c2r3__v141-a-M01-participation","page":5,"printed_page":null,"section":"III.C Energy Trading Among Microgrids","anchor_text":"an Ce(πi) = πi,j. me j∈M\\i he The overall cost of microgrid i consists of both operat- n- ing cost C","equation_id":"(18)","figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"condition"},"source_text":"It is clear that a microgrid will only participate in the trading if it can reduce its overall cost. This means that some microgrid may choose not participate in the trading. Thus, we have the following constraint: CO_i(q_i, x_n, r_{c,i}, r_{d,i}) + C_e(π_i) ≤ C_i^{Non}, ∀i ∈ M. (18) Here the left-hand side of the inequality counts the overall cost of microgrid i when participating in the energy trading. In the right-hand side, C_i^{Non} denotes the minimized cost that microgrid i can achieve without trading energy with other microgrids. In the bargaining literature we also call C_i^{Non} the disagreement point."},{"evidence_id":"v141-b-g01-e22","location":{"location_id":"src-7e85444402-p05-c2r1__v141-a-M01-pricing","page":5,"printed_page":null,"section":"III.C Energy Trading Among Microgrids","anchor_text":"NECTED MICROGRIDS 2651 ue The energy trading and payment among microgrids should di- satisfy the mar","equation_id":"(16)","figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"condition"},"source_text":"The energy trading and payment among microgrids should satisfy the market clearing constraints: e_{i,j}^t + e_{j,i}^t = 0, ∀t ∈ T, ∀j ∈ M\\i, ∀i ∈ M, (15) π_{i,j} + π_{j,i} = 0, ∀j ∈ M\\i, ∀i ∈ M. (16)"},{"evidence_id":"v141-b-g01-e27","location":{"location_id":"src-7e85444402-p05-c1r4__v141-a-M01-pricing","page":5,"printed_page":null,"section":"III.C Energy Trading Among Microgrids","anchor_text":"We consider that each microgrid i ∈M bargains with all the other interconnected microgrids to determ","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"definition"},"source_text":"We consider that each microgrid i ∈ M bargains with all the other interconnected microgrids to determine the amount of energy trading e_i = {e_{i,j}^t, ∀t ∈ T, ∀j ∈ M\\i} and the associated payment π_i = {π_{i,j}, ∀j ∈ M\\i}. Here e_{i,j}^t denotes the amount of energy that microgrid i exchanges with microgrid j in time slot t, and π_{i,j} denotes the associated payment for energy trading between microgrid i and microgrid j. If microgrid i purchases energy from microgrid j in time slot t, then e_{i,j}^t > 0; otherwise, microgrid i sells energy to microgrid j and e_{i,j}^t \u003c 0. Similarly, if microgrid i makes payment to microgrid j, then π_{i,j} > 0; otherwise microgrid i receives payment from microgrid j and π_{i,j} \u003c 0. 4Note that the payments π_i are determined through bargaining between microgrids, and are not necessary linear in terms of the energy exchange e_i."},{"evidence_id":"v141-b-g02-E17","location":{"location_id":"src-7e85444402-p06-c2r2__v141-a-M01-clearing","page":6,"printed_page":"2652","section":"IV. PROBLEM ANALYSIS","anchor_text":"BP can be decomposed into two sequential subproblems on energy d- trading & scheduling and trading p","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-06.png","occurrence_role":"definition"},"source_text":"Theorem 1: The energy-trading bargaining problem NBP can be decomposed into two sequential subproblems on energy trading & scheduling and trading payment, denoted as P1 and P2, respectively. In the first step, we solve a social operating cost minimization problem P1 for the interconnected-microgrids system, which yields the optimal energy scheduling and energy trading for all microgrids. Those microgrids that trade energy with other microgrids form the set M′. In the second step, microgrids in set M′ bargain with each other to determine the energy-trading payments in P2."},{"evidence_id":"v141-b-g02-E18","location":{"location_id":"src-7e85444402-p06-c2r2__v141-a-M01-clearing","page":6,"printed_page":"2652","section":"IV. PROBLEM ANALYSIS","anchor_text":"BP can be decomposed into two sequential subproblems on energy d- trading & scheduling and trading p","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-06.png","occurrence_role":"definition"},"source_text":"P1: Social operating cost minimization problem:\nmin ∑_{i∈M} CO_i(q_i, x_n, r_{c,i}, r_{d,i})\nsubject to (1)–(3), (5), (6), (8)–(11), (14), (15), and (17),\nvariables: { g_i, q_i, x_n, r_{c,i}, r_{d,i}, e_i, i ∈ M }.\nSolving P1 determines the optimal energy trading & scheduling {g_i^*, q_i^*, x_n^*, r_{c,i}^*, r_{d,i}^*, e_i^*} for each microgrid i ∈ M. If a microgrid i has a nonzero energy trading vector e_i, then it belongs to set M′, and will participate in the payment bargaining in Problem P2. For the non-trading microgrids j ∈ M\\M′, they do not participate in the payment bargaining and their operating costs are the same as the disagreement points C_j^{Non}."},{"evidence_id":"v141-b-g02-E19","location":{"location_id":"src-7e85444402-p06-c2r3__v141-a-M01-pricing","page":6,"printed_page":"2652","section":"IV. PROBLEM ANALYSIS","anchor_text":"scheduling {gi , qi , xn, rc,i, rd,i, ei } for each microgrid i ∈M. us If a microgrid i has a nonzer","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-06.png","occurrence_role":"definition"},"source_text":"P2: Payment bargaining problem:\nmax ∏_{i∈M′} ( δ_i^* − Ce(π_i) )\nsubject to (16) and (18),\nvariables: { π_i, i ∈ M′ },\nwhere δ_i^* ≜ C_i^{Non} − CO_i(q_i^*, x_n^*, r_{c,i}^*, r_{d,i}^*) denotes the operating cost reduction of microgrid i based on the optimal solution of Problem P1."},{"evidence_id":"v141-b-g02-E21","location":{"location_id":"src-7e85444402-p07-c1r1__v141-a-M01-participation","page":7,"printed_page":"2653","section":"IV. PROBLEM ANALYSIS","anchor_text":"WANG AND HUANG: INCENTIVIZING ENERGY TRADING FOR INTERCONNECTED M microgrids do not contribute to th","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-07.png","occurrence_role":"condition"},"source_text":"microgrids do not contribute to the social cost minimization and won't benefit from energy trading. The only criterion for determining trading and non-trading microgrids is whether they can contribute to the social cost minimization. Secondly, after identifying those microgrids who do not want to participate in the energy trading, we then focus on the rest of the microgrids who trade energy. We decide a fair allocation of benefits to each of participated microgrids through the payment bargaining problem P2."},{"evidence_id":"v141-b-g02-E37","location":{"location_id":"src-7e85444402-p08-c2r4__v141-a-M01-activation","page":8,"printed_page":"2654","section":"V.C Algorithm Design and Implementation","anchor_text":"To implement the solution method for solving the energy trading and payment problems P1 and P2, we d","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-08.png","occurrence_role":"definition"},"source_text":"We introduce the concept of virtual clearing house for solving the higher level problem. The virtual clearing house is a communication and computing module, which provides clearing service of energy trading and payment for all the microgrids. At the beginning of each daily operation, the virtual clearing house updates the auxiliary and dual variables according to (21), (22) and (25), (26), and broadcasts to all participating microgrids when solving P1 and P2, respectively. All the participating microgrids concurrently solve P1-MGi and P2-MGi and report their energy trading schedules and payments to the virtual clearing house."},{"evidence_id":"v141-b-g01-e23","location":{"location_id":"src-7e85444402-p05-c2r2__v141-a-M01-pricing","page":5,"printed_page":null,"section":"III.C Energy Trading Among Microgrids","anchor_text":"o- j∈M\\i n∈Ni ed ∀t ∈T , ∀i ∈M, (17) nd where j∈M\\i eti,j is the net energy traded between microgrid","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"definition"},"source_text":"Compared with the cost function of microgrid i in Problem P-MG_i, the interconnected microgrid has an extra cost that is the payment to other microgrids, i.e., C_e(π_i) = Σ_{j∈M\\i} π_{i,j}. The overall cost of microgrid i consists of both operating cost C_i^O(q_i, x_n, r_{c,i}, r_{d,i}) and trading payment C_e(π_i)."},{"evidence_id":"v141-b-g02-E10","location":{"location_id":"src-7e85444402-p05-c2r1__v141-a-M01-pricing","page":5,"printed_page":"2651","section":"III.C Energy Trading Among Microgrids","anchor_text":"NECTED MICROGRIDS 2651 ue The energy trading and payment among microgrids should di- satisfy the mar","equation_id":"(16)","figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"condition"},"source_text":"π_{i,j} + π_{j,i} = 0,   ∀j ∈ M\\i, ∀i ∈ M.   (16)   The energy trading and payment among microgrids should satisfy the market clearing constraints: ..."},{"evidence_id":"v141-b-g02-E12","location":{"location_id":"src-7e85444402-p05-c2r2__v141-a-M01-pricing","page":5,"printed_page":"2651","section":"III.C Energy Trading Among Microgrids","anchor_text":"o- j∈M\\i n∈Ni ed ∀t ∈T , ∀i ∈M, (17) nd where j∈M\\i eti,j is the net energy traded between microgrid","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"definition"},"source_text":"Compared with the cost function of microgrid i in Problem P-MGi, the interconnected microgrid has an extra cost that is the payment to other microgrids, i.e.,\nCe(π_i) = ∑_{j∈M\\i} π_{i,j}."},{"evidence_id":"v141-b-g02-E13","location":{"location_id":"src-7e85444402-p05-c2r3__v141-a-M01-participation","page":5,"printed_page":"2651","section":"III.C Energy Trading Among Microgrids","anchor_text":"an Ce(πi) = πi,j. me j∈M\\i he The overall cost of microgrid i consists of both operat- n- ing cost C","equation_id":"(18)","figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"condition"},"source_text":"It is clear that a microgrid will only participate in the trading if it can reduce its overall cost. This means that some microgrid may choose not participate in the trading. Thus, we have the following constraint:\nCO_i(q_i, x_n, r_{c,i}, r_{d,i}) + Ce(π_i) ≤ C_i^{Non},   ∀i ∈ M.   (18)\nHere the left-hand side of the inequality counts the overall cost of microgrid i when participating in the energy trading. In the right-hand side, C_i^{Non} denotes the minimized cost that microgrid i can achieve without trading energy with other microgrids. In the bargaining literature we also call C_i^{Non} the disagreement point."}],"field_notes":{"empty_E_reason":null,"empty_x_reason":null,"empty_theta_reason":null},"evidence_basis":"explicit","implementation_status":"unimplemented","status":"needs_review","lead_ids":["v141-a-M01-activation","v141-a-M01-clearing","v141-a-M01-coordination","v141-a-M01-participation","v141-a-M01-pricing","v141-a-M01-validation"],"extras":{"decision_anchor":"settlement.payment","graph_fact_supports":[[{"evidence_id":"v141-b-g02-E17","quote":"In the first step, we solve a social operating cost minimization problem P1 for the interconnected-microgrids system, which yields the optimal energy scheduling and energy trading for all microgrids. Those microgrids that trade energy with other microgrids form the set M′. In the second step, microgrids in set M′ bargain with each other to determine the energy-trading payments in P2."}],[{"evidence_id":"v141-b-g02-E19","quote":"P2: Payment bargaining problem: max ∏_{i∈M′} ( δ_i^* − Ce(π_i) ) subject to (16) and (18), variables: { π_i, i ∈ M′ }, where δ_i^* ≜ C_i^{Non} − CO_i(q_i^*, x_n^*, r_{c,i}^*, r_{d,i}^*) denotes the operating cost reduction of microgrid i based on the optimal solution of Problem P1."}],[{"evidence_id":"v141-b-g02-E18","quote":"If a microgrid i has a nonzero energy trading vector e_i, then it belongs to set M′, and will participate in the payment bargaining in Problem P2. For the non-trading microgrids j ∈ M\\M′, they do not participate in the payment bargaining"}],[{"evidence_id":"v141-b-g02-E21","quote":"Secondly, after identifying those microgrids who do not want to participate in the energy trading, we then focus on the rest of the microgrids who trade energy. We decide a fair allocation of benefits to each of participated microgrids through the payment bargaining problem P2."},{"evidence_id":"v141-b-g02-E17","quote":"Those microgrids that trade energy with other microgrids form the set M′."}],[{"evidence_id":"v141-b-g02-E37","quote":"The virtual clearing house is a communication and computing module, which provides clearing service of energy trading and payment for all the microgrids."}],[{"evidence_id":"v141-b-g01-e22","quote":"π_{i,j} + π_{j,i} = 0, ∀j ∈ M\\i, ∀i ∈ M. (16)"}],[{"evidence_id":"v141-b-g01-e05","quote":"Thus, we have the following constraint: CO_i(q_i, x_n, r_{c,i}, r_{d,i}) + C_e(π_i) ≤ C_i^{Non}, ∀i ∈ M. (18)"},{"evidence_id":"v141-b-g01-e05","quote":"In the right-hand side, C_i^{Non} denotes the minimized cost that microgrid i can achieve without trading energy with other microgrids."}],[{"evidence_id":"v141-b-g01-e27","quote":"Note that the payments π_i are determined through bargaining between microgrids, and are not necessary linear in terms of the energy exchange e_i."}]],"C2_formalization":{"graph_sha256":"c57fafeac84dc6b710c1ec2a244ef939c54f8456bd432e2397b4b1d23f9f40ad","applicability":"formalized","reason":"Market payment (settlement) rule. The frozen rule contains explicit source mathematics, transcribed faithfully here (formalization_origin=source): the bilateral payment-netting equation pi_{i,j}+pi_{j,i}=0 (16) [v141-b-g01-e22]; the individual-rationality constraint CO_i(q_i,x_n,r_{c,i},r_{d,i})+C_e(pi_i) \u003c= C_i^{Non} (18) [v141-b-g01-e05]; the P2 payment-bargaining objective max prod_{i in M'}(delta_i^* - C_e(pi_i)) s.t. (16),(18) [v141-b-g02-E19]; the operating-cost-reduction definition delta_i^* := C_i^{Non} - CO_i(q_i^*,x_n^*,r_{c,i}^*,r_{d,i}^*) [v141-b-g02-E19]; the per-microgrid payment aggregation C_e(pi_i)=sum_{j in M\\i} pi_{i,j} [v141-b-g01-e23, v141-b-g02-E12]; and the M' eligibility condition on a nonzero trading vector e_i [v141-b-g02-E18]. Decision objects of this settlement stage are the bargained payments pi_i / pi_{i,j}; the operating quantities (q_i, x_n, r_{c,i}, r_{d,i}) and the energy-trading vector e_i are inputs fixed by the preceding P1 clearing solution, so they are treated as fixed inputs (e_i is declared as a fixed input parameter because it is a decision variable of P1/clearing, not of this settlement rule). Constraints C001 (P1-before-P2 sequencing), C004 (M' identification before benefit allocation), C005 (virtual clearing-house payment service) and C008 (bargained payments need not be linear in exchanged energy) are procedural/qualitative with no closed-form source expression and remain not_formalized. All B evidence referenced here is unreviewed candidate support: no independent source audit was performed and no source correctness is claimed.","bindings":[{"object_id":"v141-c-R009-x-pi-ij","node_ids":["settlement.payment"],"edge_ids":["v141-c-R009-E001","v141-c-R009-E005"],"rationale":"π_{i,j} is the bilateral payment object concretizing the settlement.payment function; it is the P2 decision variable that links the P1 social-welfare solution to payments (edge E001) and its participation is conditional on nonzero inter-microgrid trade (edge E005)."},{"object_id":"v141-c-R009-x-pi-i","node_ids":["settlement.payment"],"edge_ids":["v141-c-R009-E002","v141-c-R009-E003"],"rationale":"π_i is the per-microgrid payment vector decided in P2, which follows P1 (precedes edge E002), and is cleared by the virtual clearing house (coordination.local_operator → settlement.payment, edge E003)."},{"object_id":"v141-c-R009-th-non","node_ids":["settlement.payment"],"edge_ids":["v141-c-R009-E001","v141-c-R009-E002"],"rationale":"C_i^{Non} is the disagreement-point benchmark that bounds the payment-inclusive cost in (18) and shifts the gain in the P2 objective; it connects the social-welfare solution to payments through edges E001/E002."},{"object_id":"v141-c-R009-th-delta","node_ids":["clearing.social_welfare","settlement.payment"],"edge_ids":["v141-c-R009-E001"],"rationale":"δ_i^* is the operating cost reduction of microgrid i at the P1 optimum and is the gain term of the P2 Nash product; it directly instantiates the clearing.social_welfare → settlement.payment links edge E001."},{"object_id":"v141-c-R009-th-ei","node_ids":["clearing.inter_area","settlement.payment"],"edge_ids":["v141-c-R009-E004","v141-c-R009-E005"],"rationale":"e_i is the P1-optimal inter-microgrid trading vector (clearing.inter_area); its nonzero value determines membership in M′ (matching.counterparties precedes edge E004) and conditions P2 payment eligibility (conditional_on edge E005)."},{"object_id":"v141-c-R009-C001","node_ids":["clearing.social_welfare","settlement.payment"],"edge_ids":["v141-c-R009-E002"],"rationale":"The P1-before-P2 sequencing is the precedes edge E002 from clearing.social_welfare to settlement.payment."},{"object_id":"v141-c-R009-C002","node_ids":["clearing.social_welfare","settlement.payment"],"edge_ids":["v141-c-R009-E001"],"rationale":"The P2 Nash-product objective ties the P1 social-welfare optimum to the bargained payments, i.e., the links edge E001."},{"object_id":"v141-c-R009-C003","node_ids":["settlement.payment","clearing.inter_area"],"edge_ids":["v141-c-R009-E005"],"rationale":"P2 payment eligibility conditional on a nonzero inter-microgrid trading allocation is the conditional_on edge E005 from settlement.payment to clearing.inter_area."},{"object_id":"v141-c-R009-C004","node_ids":["matching.counterparties","settlement.payment"],"edge_ids":["v141-c-R009-E004"],"rationale":"Identifying the trading group M′ before allocating its benefits is the precedes edge E004 from matching.counterparties to settlement.payment."},{"object_id":"v141-c-R009-C005","node_ids":["coordination.local_operator","settlement.payment"],"edge_ids":["v141-c-R009-E003"],"rationale":"The virtual clearing house's payment-clearing service is the links edge E003 from coordination.local_operator to settlement.payment."},{"object_id":"v141-c-R009-C006","node_ids":["settlement.payment"],"edge_ids":[],"rationale":"Bilateral payment netting is an internal constraint on the settlement.payment object and needs no graph edge to be expressed."},{"object_id":"v141-c-R009-C007","node_ids":["settlement.payment"],"edge_ids":[],"rationale":"The individual-rationality bound restricts the net payment captured by settlement.payment; the operating-cost terms are fixed P1 inputs and are not represented by any edge of this rule's E."},{"object_id":"v141-c-R009-C008","node_ids":["settlement.payment"],"edge_ids":[],"rationale":"The non-linearity of bargained payments is a property of the settlement.payment object."},{"object_id":"v141-c-R009-C009","node_ids":["settlement.payment"],"edge_ids":[],"rationale":"The payment aggregation C_e(π_i)=Σ_{j∈M\\i}π_{i,j} is an internal definition of the settlement.payment object."},{"object_id":"v141-c-R009-C010","node_ids":["clearing.social_welfare","settlement.payment"],"edge_ids":["v141-c-R009-E001"],"rationale":"The definition of δ_i^* uses the P1 social-cost optimum and feeds the P2 payment objective, instantiating edge E001."}],"revision_requests":[]}},"quarantined_references":[]}});
